@r1.c1 w.request.constraint request=$r1 on=attribute attribute=preference.scope value="for every session from now on" operator=eq phase=result

@f1 w.request.filler text=please
@r1 w.request.request act=change mood=do predicate=make words="Could you please make my avatar the woman"
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="avatar the woman" note=pref.avatar.figure value="the woman"
@r2 w.request.request act=save mood=do words="remember that choice for later, when I open a new tab" predicate=remember
@r2.t w.request.target request=$r2 family=preference mode=existing determiner=definite fill=description description="that choice"
@r2.l1 w.request.lookup request=$r2 target=$r2.t key=thing from=page
@r2.c1 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="when I open a new tab" operator=eq phase=result
@r2.c2 w.request.constraint request=$r2 on=attribute attribute=preference.scope value="for later" operator=eq phase=result

@r1 w.request.request act=change mood=do words="my avatar should stay a lady until I tell you otherwise" predicate=should
@r1.t w.request.target request=$r1 family=drawn mode=existing determiner=possessive fill=context sort=avatar
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.u1 w.request.unread request=$r1 text="stay a lady" note=pref.avatar.figure value="a lady"
@f1 w.request.filler text="Whatever else changes on the page"
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=preference.scope value="until I tell you otherwise" operator=eq phase=result
